/* Max Motion — compact, local WebGL effects rack. No remote assets or models. */
const FX = (() => {
  const range=(key,label,min,max,init)=>({key,label,min,max,init}), color=(key,label,init)=>({key,label,init});
  const tools=[
    ['key','كروما','احذف لونًا متجانسًا واستبدله بلون آخر. ليست إزالة خلفية بالذكاء الاصطناعي.',[color('keyColor','اللون المحذوف','#00ff00'),color('back','لون الخلفية','#142334'),range('threshold','نطاق اللون',1,100,24),range('feather','نعومة الحافة',1,100,16),range('despill','تنظيف الحواف',0,100,60),range('invert','عكس التحديد',0,1,0)]],
    ['blur','تمويه','طمس كامل الصورة أو الجزء الواقع داخل دائرة ناعمة.',[range('radius','نصف قطر التمويه',1,100,34),range('area','نطاق دائري (صفر = كامل الكادر)',0,100,0),range('cx','مركز أفقي',0,100,50),range('cy','مركز رأسي',0,100,50)]],
    ['glow','توهّج','انشر هالة حول المناطق المضيئة من الصورة.',[range('amount','قوة التوهّج',0,100,60),range('size','انتشار الهالة',1,100,36),range('gate','عتبة الإضاءة',0,100,48),color('glowColor','لون الهالة','#ffdcaf')]],
    ['rain','مطر','طبقتان من قطرات متحرّكة. شغّل المعاينة لرؤية اتجاه المطر.',[range('rainAmt','الكثافة',0,100,66),range('speed','السرعة',1,100,44),range('wind','ميل الريح',-100,100,-25),range('rainMix','وضوح القطرات',0,100,68)]],
    ['frost','جليد خفيف','بلورات على الأطراف مع مركز قابل للضبط.',[range('ice','قوة الجليد',0,100,58),range('edge','امتداد الأطراف',1,100,55),range('grain','حجم البلورات',1,100,40),color('iceColor','لون الجليد','#c8edff')]],
    ['motion','تمويه الحركة','خطوط تمويه في اتجاه تختاره؛ هذا تقريب بصري وليس تتبّع حركة.',[range('distance','طول الأثر',1,100,46),range('angle','زاوية الاتجاه',0,180,28),range('blend','مزج مع الأصل',0,100,85)]],
    ['light','إضاءة وتعتيم','صحّح التعريض بالموجب أو السالب واضبط الدرجات المتوسطة.',[range('exposure','التعريض (أعشار وقفة)',-30,30,-8),range('gamma','الدرجات المتوسطة',-80,80,0),range('offset','إزاحة السطوع',-100,100,0)]],
    ['contrast','تباين','غيّر التباين وحدّد الدرجة التي يدور حولها التعديل.',[range('contrastAmt','التباين',-100,100,32),range('pivot','نقطة الارتكاز',5,95,50)]],
    ['sat','تشبّع','تحكّم بكل الألوان أو عزّز الألوان الباهتة بشكل انتقائي.',[range('saturation','التشبّع',-100,100,32),range('vibrance','حيوية الألوان',-100,100,10)]],
    ['temp','توازن اللون','دفء وبرودة مع تصحيح انحراف الأخضر والأرجواني.',[range('temperature','حرارة اللون',-100,100,35),range('tint','أخضر / أرجواني',-100,100,0)]]
  ].map(([id,name,desc,params])=>({id,name,desc,params}));
  const schema=Object.fromEntries(tools.map(t=>[t.id,t]));const defaults=id=>Object.fromEntries(schema[id].params.map(p=>[p.key,p.init]));
  const canvas=document.createElement('canvas');let gl,program,tex,u={},lost=false;
  const uniforms=tools.flatMap(t=>['uniform float on_'+t.id+';',...t.params.map(p=>'uniform '+(p.min==null?'vec3':'float')+' '+p.key+';')]).join('\n');
  const fragment=`precision highp float;varying vec2 uv;uniform sampler2D src;uniform vec2 aspect;uniform float time;
${uniforms}
float lum(vec3 c){return dot(c,vec3(.2126,.7152,.0722));}
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*4375.5453);}
vec3 sampleAt(vec2 p){vec3 c=texture2D(src,clamp(p,0.,1.)).rgb;if(on_key>.5){vec3 cc=c/(.16+c.r+c.g+c.b),kk=keyColor/(.16+keyColor.r+keyColor.g+keyColor.b);float diff=length(cc-kk)+abs(lum(keyColor)-lum(c))*.12;float a=smoothstep(threshold*.0075,threshold*.0075+feather*.0039,diff);if(invert>.5)a=1.-a;vec3 tintAxis=normalize(keyColor-vec3(lum(keyColor))+vec3(.0001));c-=tintAxis*max(0.,dot(c-vec3(lum(c)),tintAxis))*(1.-a)*despill*.01;c=mix(back,c,a);}return c;}
float streak(vec2 p,float scale,float seed){p.x-=p.y*wind*.004;p*=vec2(scale,scale*.45);p.y-=time*(.6+speed*.055)+seed;vec2 cell=floor(p);float h=hash(cell+seed);vec2 f=fract(p);float x=abs(f.x-(.12+.76*h)),y=abs(f.y-.5);return (1.-smoothstep(.012,.065,x))*(1.-smoothstep(.03,.42,y))*step(h, rainAmt*.01);}
float crystal(vec2 p){vec2 i=floor(p), f=fract(p);float a=8.,b=8.;for(int x=-1;x<=1;x++){for(int y=-1;y<=1;y++){vec2 n=vec2(float(x),float(y));vec2 v=n+.18+.64*vec2(hash(i+n),hash(i+n+41.))-f;float h=dot(v,v);if(h<a){b=a;a=h;}else b=min(b,h);}}return 1.-smoothstep(.009,.09,b-a);}
void main(){vec2 p=uv;vec3 c=sampleAt(p);if(on_blur>.5){vec3 sum=c*2.;float weight=2.;for(int i=1;i<=24;i++){float fi=float(i),a=fi*2.39996;vec2 off=vec2(cos(a),sin(a))*sqrt(fi/24.)*radius*.00055/aspect;float w=1.-fi/32.;sum+=sampleAt(p+off)*w;weight+=w;}float mask=area<.1?1.:1.-smoothstep(.004+area*.005,.046+area*.005,length((p-vec2(cx,cy)*.01)*aspect));c=mix(c,sum/weight,mask);}
if(on_motion>.5){vec2 axis=vec2(cos(radians(angle)),sin(radians(angle)))*distance*.00065/aspect;vec3 sum=vec3(0.);for(int i=-7;i<=7;i++)sum+=sampleAt(p+axis*float(i)/7.);c=mix(c,sum/15.,blend*.01*(on_blur>.5?.62:1.));}
if(on_temp>.5)c+=vec3(.14*temperature+.05*tint,-.09*tint,-.14*temperature+.05*tint)*.01;
if(on_light>.5)c=pow(max(c*exp2(exposure*.1)+offset*.004,vec3(0.)),vec3(exp2(-gamma*.013)));
if(on_contrast>.5)c=(c-pivot*.01)*exp2(contrastAmt*.019)+pivot*.01;
if(on_sat>.5){float span=max(max(c.r,c.g),c.b)-min(min(c.r,c.g),c.b);c=mix(vec3(lum(c)),c,max(0.,1.+saturation*.01+vibrance*.009*(1.-clamp(span,0.,1.))));}
if(on_glow>.5){vec3 sum=vec3(0.);for(int i=0;i<20;i++){float k=float(i),a=k*2.39996;vec3 n=sampleAt(p+vec2(cos(a),sin(a))*sqrt(k/19.)*size*.0009/aspect);sum+=n*smoothstep(gate*.0095,gate*.0095+.15,lum(n));}c+=sum*.0012*amount*glowColor;}
if(on_rain>.5){float s=streak(p*aspect,26.,4.)*.62+streak(p*aspect,51.,32.)*.53;c=mix(c,vec3(.8,.91,1.),clamp(s*rainMix*.014,0.,1.));}
if(on_frost>.5){float nearest=min(min(p.x,1.-p.x)*aspect.x,min(p.y,1.-p.y)*aspect.y);float rim=1.-smoothstep(0.,edge*.004+.025,nearest);float vein=crystal(p*aspect*(67.-grain*.49));float mist=.22+.67*vein+.15*hash(floor(p*aspect*360.));c=mix(c,iceColor,clamp(ice*.013*rim*mist,0.,1.));}gl_FragColor=vec4(clamp(c,0.,1.),1.);}`;
  function init(){if(program&&!lost)return;gl=canvas.getContext('webgl',{alpha:false,antialias:false,preserveDrawingBuffer:true,depth:false,stencil:false});if(!gl||gl.isContextLost())throw Error('محرّك المؤثرات WebGL غير متاح.');function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s}const vs=shader(gl.VERTEX_SHADER,'attribute vec2 xy;varying vec2 uv;void main(){uv=vec2(xy.x*.5+.5,.5-xy.y*.5);gl_Position=vec4(xy,0.,1.);}');const fs=shader(gl.FRAGMENT_SHADER,fragment);program=gl.createProgram();gl.attachShader(program,vs);gl.attachShader(program,fs);gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS)){program=null;throw Error('تعذّر ربط مؤثرات الصورة.')}gl.useProgram(program);let b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);let l=gl.getAttribLocation(program,'xy');gl.enableVertexAttribArray(l);gl.vertexAttribPointer(l,2,gl.FLOAT,false,0,0);tex=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tex);for(const k of ['TEXTURE_WRAP_S','TEXTURE_WRAP_T'])gl.texParameteri(gl.TEXTURE_2D,gl[k],gl.CLAMP_TO_EDGE);for(const k of ['TEXTURE_MIN_FILTER','TEXTURE_MAG_FILTER'])gl.texParameteri(gl.TEXTURE_2D,gl[k],gl.LINEAR);u={};for(let i=0;i<gl.getProgramParameter(program,gl.ACTIVE_UNIFORMS);i++){let {name}=gl.getActiveUniform(program,i);u[name]=gl.getUniformLocation(program,name)}lost=false;}
  canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();lost=true;program=null});canvas.addEventListener('webglcontextrestored',()=>{lost=false;program=null});
  function render(video,state,w,h,t){if(!state||!Object.keys(state).length)return video;init();if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}gl.viewport(0,0,w,h);gl.uniform2f(u.aspect,w/Math.min(w,h),h/Math.min(w,h));gl.uniform1f(u.time,t);for(const tool of tools){let v=state[tool.id];gl.uniform1f(u['on_'+tool.id],v?1:0);if(!v)continue;for(const p of tool.params){if(p.min!=null)gl.uniform1f(u[p.key],v[p.key]);else{let n=parseInt(v[p.key].slice(1),16);gl.uniform3f(u[p.key],(n>>16)/255,((n>>8)&255)/255,(n&255)/255)}}}gl.texImage2D(gl.TEXTURE_2D,0,gl.RGB,gl.RGB,gl.UNSIGNED_BYTE,video);gl.drawArrays(gl.TRIANGLES,0,3);return canvas}
  return {tools,schema,defaults,init,render};
})();
